def drop_min_color_shape(grid, color=9, bg=0):
    """Erase every shape (8-connected nonzero component) containing the fewest cells of the given color."""
    g=[r[:] for r in grid]
    comps=shapes8(g)
    counts=[sum(1 for y,x in c if g[y][x]==color) for c in comps]
    m=min(counts)
    for c,k in zip(comps,counts):
